using System;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;
class DesignTests{
 static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;static object Get(object f,string n){return f.GetType().GetField(n,flags).GetValue(f);}
 [STAThread]static void Main(){Application.EnableVisualStyles();ProfileStore.FileName=Path.Combine(Path.GetTempPath(),"Lume-design-"+Guid.NewGuid(),"profiles.json");using(var f=new LumeStudio()){f.Show();foreach(var size in new[]{new Size(1280,730),new Size(880,600),new Size(1366,730),new Size(2560,1400)}){f.ClientSize=size;Application.DoEvents();var cards=(List<LightCard>)Get(f,"cards");foreach(var c in cards){if(c.Test.Bounds.IntersectsWith(c.Status.Bounds))throw new Exception("Overlapping card actions");if(c.Status.Bottom>c.Height)throw new Exception("Clipped status");}using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine("..","design-"+size.Width+".png"));}}var states=((List<LightCard>)Get(f,"cards")).Select(c=>c.State.Copy()).ToArray();using(var editor=new EffectEditor(16,new EffectOptions(),3,states)){editor.Show();Application.DoEvents();using(var b=new Bitmap(editor.Width,editor.Height)){editor.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save("../design-editor.png");}editor.Close();}typeof(LumeStudio).GetField("exitRequested",flags).SetValue(f,true);f.Close();}Console.WriteLine("PASS: card action bounds at 880, 1280, 1366; effect editor rendered; no device commands.");}}
